/**
 * Whether text inserted at the start or end of a span is styled by it. `INCLUSIVE_EXCLUSIVE`
 * includes text inserted at the start and not at the end.
 */
export const SPAN: {
  readonly INCLUSIVE_EXCLUSIVE: 0x11
  readonly INCLUSIVE_INCLUSIVE: 0x12
  readonly EXCLUSIVE_EXCLUSIVE: 0x21
  readonly EXCLUSIVE_INCLUSIVE: 0x22
}
